ANTHROPIC_MODEL_MAP = CONFIG.get("anthropic_model_map", {
    "claude-sonnet-4-6": "deepseek-chat",
    "claude-sonnet-4-5": "deepseek-chat",
    "claude-opus-4-5": "deepseek-reasoner",
    "claude-opus-4-1": "deepseek-reasoner",
})


def anthropic_to_openai(anthropic_body: dict) -> dict:
    """将 Anthropic Messages API 请求转为 OpenAI Chat Completions 格式"""
    openai_body = {}

    # 模型映射
    anthropic_model = anthropic_body.get("model", "")
    openai_model = ANTHROPIC_MODEL_MAP.get(
        anthropic_model,
        CONFIG.get("default_anthropic_model", "deepseek-chat"),
    )
    openai_body["model"] = openai_model

    # messages 转换
    openai_messages = []

    # system prompt → system message
    system_text = anthropic_body.get("system")
    if isinstance(system_text, list):
        # Anthropic 可能发 system 为数组 [{type: "text", text: "..."}]
        system_parts = []
        for s in system_text:
            if isinstance(s, dict) and s.get("type") == "text":
                system_parts.append(s.get("text", ""))
        system_text = "\n".join(system_parts) if system_parts else ""
    if system_text:
        openai_messages.append({"role": "system", "content": system_text})

    for msg in anthropic_body.get("messages", []):
        role = msg.get("role", "user")
        content = msg.get("content", "")

        if isinstance(content, list):
            # Anthropic content 数组: [{type: "text", text: "..."}, {type: "tool_use", ...}, ...]
            text_parts = []
            tool_results = []
            for block in content:
                if isinstance(block, dict):
                    if block.get("type") == "text":
                        text_parts.append(block.get("text", ""))
                    elif block.get("type") == "tool_result":
                        tool_results.append(block)
                    elif block.get("type") == "tool_use":
                        # assistant 的 tool_use → 需要转成 OpenAI tool_calls
                        pass  # 在 assistant 转换时处理
            content = "\n".join(text_parts) if text_parts else ""

            # 处理 tool_result 消息
            if tool_results and not text_parts:
                # 这是个纯 tool result 消息
                for tr in tool_results:
                    tr_content = tr.get("content", "")
                    if isinstance(tr_content, list):
                        tr_content = "\n".join(
                            b.get("text", "") for b in tr_content if isinstance(b, dict) and b.get("type") == "text"
                        )
                    openai_messages.append({
                        "role": "tool",
                        "tool_call_id": tr.get("tool_use_id", ""),
                        "content": str(tr_content),
                    })
                continue

        # 处理 assistant 消息中的 tool_use
        if role == "assistant" and isinstance(msg.get("content"), list):
            tool_calls = []
            text_content = None
            for block in msg["content"]:
                if isinstance(block, dict):
                    if block.get("type") == "text":
                        text_content = block.get("text", "")
                    elif block.get("type") == "tool_use":
                        tool_calls.append({
                            "id": block.get("id", ""),
                            "type": "function",
                            "function": {
                                "name": block.get("name", ""),
                                "arguments": json.dumps(block.get("input", {})),
                            },
                        })
            if tool_calls:
                openai_msg = {"role": "assistant", "content": text_content}
                openai_msg["tool_calls"] = tool_calls
                openai_messages.append(openai_msg)
                continue

        openai_messages.append({"role": role, "content": content})

    openai_body["messages"] = openai_messages

    # 参数映射
    if "max_tokens" in anthropic_body:
        openai_body["max_tokens"] = anthropic_body["max_tokens"]
    if "temperature" in anthropic_body:
        openai_body["temperature"] = anthropic_body["temperature"]
    if "top_p" in anthropic_body:
        openai_body["top_p"] = anthropic_body["top_p"]
    if "top_k" in anthropic_body:
        openai_body["top_k"] = anthropic_body["top_k"]
    if "stop_sequences" in anthropic_body:
        openai_body["stop"] = anthropic_body["stop_sequences"]
    if "stream" in anthropic_body:
        openai_body["stream"] = anthropic_body["stream"]

    # 工具定义转换 Anthropic → OpenAI
    anthropic_tools = anthropic_body.get("tools", [])
    if anthropic_tools:
        openai_tools = []
        for tool in anthropic_tools:
            openai_tools.append({
                "type": "function",
                "function": {
                    "name": tool.get("name", ""),
                    "description": tool.get("description", ""),
                    "parameters": tool.get("input_schema", {"type": "object", "properties": {}}),
                },
            })
        openai_body["tools"] = openai_tools

    return openai_body


def openai_to_anthropic(openai_data: dict, model: str) -> dict:
    """将 OpenAI Chat Completions 响应转为 Anthropic Messages 格式"""
    choice = openai_data.get("choices", [{}])[0]
    message = choice.get("message", {})
    finish_reason = choice.get("finish_reason", "stop")
    usage = openai_data.get("usage", {})

    # stop_reason 映射
    stop_reason_map = {
        "stop": "end_turn",
        "length": "max_tokens",
        "tool_calls": "tool_use",
        "content_filter": "end_turn",
    }
    stop_reason = stop_reason_map.get(finish_reason, "end_turn")

    # 构建 anthropic content
    content_blocks = []

    # 文本内容
    text = message.get("content", "")
    if text:
        content_blocks.append({"type": "text", "text": text})

    # 工具调用转换 OpenAI → Anthropic
    tool_calls = message.get("tool_calls", [])
    for tc in tool_calls:
        func = tc.get("function", {})
        try:
            tool_input = json.loads(func.get("arguments", "{}"))
        except (json.JSONDecodeError, TypeError):
            tool_input = {}
        content_blocks.append({
            "type": "tool_use",
            "id": tc.get("id", ""),
            "name": func.get("name", ""),
            "input": tool_input,
        })

    return {
        "id": openai_data.get("id", ""),
        "type": "message",
        "role": "assistant",
        "content": content_blocks,
        "model": model,
        "stop_reason": stop_reason,
        "stop_sequence": None,
        "usage": {
            "input_tokens": usage.get("prompt_tokens", 0),
            "output_tokens": usage.get("completion_tokens", 0),
        },
    }


