@app.route("/v1/messages", methods=["POST"])
def messages():
    """Anthropic Messages API → OpenAI 翻译端点"""
    body = request.get_json(force=True)

    # 翻译请求
    try:
        openai_body = anthropic_to_openai(body)
    except Exception as e:
        stats["errors"] += 1
        return jsonify({"error": f"请求翻译失败: {str(e)}", "type": "error"}), 400

    # 找模型配置
    model_id = openai_body.get("model", "")
    model_config = get_model_config(model_id)
    if not model_config:
        stats["errors"] += 1
        return jsonify({
            "error": f"模型 {model_id} 未配置（来源: {body.get('model', 'unknown')}）",
            "type": "error",
        }), 404

    stats["total_requests"] += 1
    stream = body.get("stream", False)

    # 调用上游 OpenAI API
    result, status_code = call_upstream(model_config, openai_body)

    if status_code != 200:
        return jsonify(result), status_code

    anthropic_model = body.get("model", model_id)

    if stream:
        def generate_anthropic_stream():
            for chunk in result.iter_content(chunk_size=None):
                if not chunk:
                    continue
                # 每行 SSE 数据
                for line in chunk.decode("utf-8", errors="replace").split("\n"):
                    line = line.strip()
                    if not line or not line.startswith("data:"):
                        yield f"{line}\n".encode()
                        continue
                    data_str = line[5:].strip()
                    if data_str == "[DONE]":
                        yield "data: [DONE]\n\n".encode()
                        continue
                    try:
                        openai_chunk = json.loads(data_str)
                    except json.JSONDecodeError:
                        yield f"{line}\n".encode()
                        continue
                    # 翻译为 Anthropic SSE 格式
                    anthropic_chunk = _openai_chunk_to_anthropic_sse(openai_chunk, anthropic_model)
                    if anthropic_chunk:
                        yield f"data: {json.dumps(anthropic_chunk, ensure_ascii=False)}\n\n".encode()
        return Response(
            stream_with_context(generate_anthropic_stream()),
            content_type="text/event-stream",
        )
    else:
        anthropic_resp = openai_to_anthropic(result, anthropic_model)
        return jsonify(anthropic_resp), status_code


def _openai_chunk_to_anthropic_sse(chunk: dict, model: str) -> dict | None:
    """将 OpenAI SSE chunk 转为 Anthropic SSE event"""
    choices = chunk.get("choices", [])
    if not choices:
        return None

    choice = choices[0]
    delta = choice.get("delta", {})
    finish_reason = choice.get("finish_reason")

    # 映射 stop_reason
    stop_reason_map = {
        "stop": "end_turn",
        "length": "max_tokens",
        "tool_calls": "tool_use",
    }

    event = {
        "type": "content_block_delta",
        "index": choice.get("index", 0),
    }

    if finish_reason:
        event["delta"] = {
            "type": "text_delta",
            "text": "",
            "stop_reason": stop_reason_map.get(finish_reason, "end_turn"),
            "stop_sequence": None,
        }
    elif delta.get("content"):
        event["delta"] = {
            "type": "text_delta",
            "text": delta.get("content", ""),
        }
    elif delta.get("tool_calls"):
        # 简化处理
        return None
    else:
        return None

    event["model"] = model
    return event


